select count(*) filter (where volume is null) null_vol, count(*) filter (where not (low<=open and open<=high and low<=close and close<=high)) bad_ohlc, count(*) filter (where low<0 or open<0) neg, count(*) filter (where volume=0) zero_vol, count(*) filter (where high=low) flat_bar, count(*) total from public."Price_Stock_Indonesia_IDX" where ticker<>'IHSG' and is_final and timeframe='Daily';;
select count(*) filter (where sma_20 is null) null_sma20, count(*) filter (where rsi_14 is null) null_rsi, count(*) filter (where close is null) null_close from public."Feature_04_Technical_Indicator" where asset_type='equity' and trade_date >= '2026-01-01'
